#!/bin/bash
set -euo pipefail
test "$(id -un)" = pwa209
case "$(hostname -f)" in *.narval.calcul.quebec) ;; *) exit 2 ;; esac
module load StdEnv/2023 python/3.11.5 cuda/12.6 arrow/19.0.1
source /home/pwa209/hhw-environment/bin/activate
export PYTHONPATH=/scratch/pwa209/horsehair-worm/releases/20261021-6ed201653dfa-4f3903d7c26e/src
export PYTHONDONTWRITEBYTECODE=1
export TZ=UTC
python -B -u - <<'PY'
from pathlib import Path
import base64,hashlib,json,os,subprocess,shlex,re
from horsehair import slurm
from horsehair.core import source_identity,canonical_hash,read_json
assert os.geteuid()==3164768
r=Path('/scratch/pwa209/horsehair-worm');support=r/'maintenance/agent-coordination-repair-v9-20261103'
payload={'coordination.py': '', 'registry-wait.py': '', 'test_coordination.py': '', 'test_registry.py': '', 'test_acknowledgements.py': '', 'source-manifest.json': ''}
manifest_sha='072ecc9685d5f9b88be0fd05acf87f5d5856a6b65576275d8a9b2bcebd5230be'
assert not support.exists();support.mkdir()
for name,value in payload.items():
 with (support/name).open('xb') as f:f.write(base64.b64decode(value));f.flush();os.fsync(f.fileno())
assert hashlib.sha256((support/'source-manifest.json').read_bytes()).hexdigest()==manifest_sha
manifest=json.loads((support/'source-manifest.json').read_bytes())
for name,sha in manifest['files'].items():assert hashlib.sha256((support/name).read_bytes()).hexdigest()==sha
framework=r/'releases/20261021-6ed201653dfa-4f3903d7c26e';config=read_json(framework/'configs/study.json')
assert source_identity(framework)['sha256']=='4f3903d7c26e334a75c8f7f81ad8b865fac4e5a447ff83a8bfeae8774891d9d1'
phase='agent-coordination-qualification-v9-20261103';directory=r/'plans'/phase;directory.mkdir()
name='agent-coordination-qualification';script=directory/(name+'.sbatch');planpath=directory/'plan.json';ledger=r/'state'/(phase+'-submission.json')
argv=['python',str(support/'coordination.py'),'--mode','qualify','--source-manifest-sha256',manifest_sha,
 '--native-plan',str(planpath),'--native-ledger',str(ledger),'--native-script',str(script),'--native-task',name]
command=shlex.join(argv);text=slurm._script(config,framework,name,command,cpus=4,memory='16G',hours=1,gpu=False)
text=text.replace('set -euo pipefail','#SBATCH --hold\nset -euo pipefail',1)
script.write_text(text)
task={'name':name,'script':str(script),'script_sha256':canonical_hash(text),'depends':[],'external_dependencies':[],
 'dependency_kind':'afterany','resources':{'cpus':4,'memory':'16G','hours':1,'gpu':False,'array':None},'command':command,'coordination_manifest_sha256':manifest_sha}
plan={'schema_version':1,'root':str(r),'phase':phase,'config_sha256':canonical_hash(config),'release_identity':source_identity(framework),'tasks':[task]}
planpath.write_text(json.dumps(plan,indent=2,sort_keys=True)+'\n')
counter=[0]
def runner(cmd,**kwargs):
 counter[0]+=1;p=support/('qualification-mutation-'+str(counter[0]))
 with Path(str(p)+'-intent.json').open('x') as f:json.dump({'command':cmd},f)
 kwargs['timeout']=180;response=subprocess.run(cmd,**kwargs)
 with Path(str(p)+'-response.json').open('x') as f:json.dump({'returncode':response.returncode,'stdout':response.stdout,'stderr':response.stderr},f)
 return response
record=slurm.submit(planpath,ledger,runner=runner);job=record['tasks'][name]['job_id']
native=subprocess.run(['scontrol','show','job',job,'-o'],text=True,capture_output=True,timeout=30,check=True)
fields=dict(x.split('=',1) for x in shlex.split(native.stdout) if '=' in x)
assert not native.stderr and fields['JobId']==job and fields['UserId']=='pwa209(3164768)' and fields['JobState']=='PENDING' and fields['Reason']=='JobHeldUser'
assert fields['Command']==str(script) and fields['JobName']=='hhw-'+name and fields['Account']=='def-ptewarie_cpu' and fields['NumCPUs']=='4' and fields['MinMemoryNode'] in ['16G','16384M'] and fields['TimeLimit']=='01:00:00'
with (support/'qualification-held.json').open('x') as f:json.dump(fields,f,indent=2)
response=runner(['scontrol','release',job],text=True,capture_output=True);response.check_returncode();assert not response.stderr
receipt={'status':'registered_and_released_qualification','job_id':job,'source_manifest_sha256':manifest_sha,'plan':str(planpath),'ledger':str(ledger)}
with (support/'qualification-registration.json').open('x') as f:json.dump(receipt,f,indent=2)
print('COORDINATION_REGISTRATION_919 '+json.dumps(receipt),flush=True)
PY
